   463→	if request == nil || request.Count == 0 || len(request.Columns) == 0 {
   464→		return nil, nil
   465→	}
   466→
   467→	beaconConfig := params.BeaconConfig()
   468→	numberOfColumns := beaconConfig.NumberOfColumns
   469→	maxRequestDataColumnSidecars := params.BeaconConfig().MaxRequestDataColumnSidecars
   470→
   471→	// Check if we do not request too many sidecars.
   472→	columnsCount := uint64(len(request.Columns))
   473→	totalCount := request.Count * columnsCount
   474→	if totalCount > maxRequestDataColumnSidecars {
   475→		return nil, errors.Wrapf(errMaxRequestDataColumnSidecarsExceeded, "requestedCount=%d, allowedCount=%d", totalCount, maxRequestDataColumnSidecars)
   476→	}
   477→
   478→	// Build the topic.
   479→	currentSlot := p.Tor.CurrentSlot()
   480→	currentEpoch := slots.ToEpoch(currentSlot)
   481→	topic, err := p2p.TopicFromMessage(p2p.DataColumnSidecarsByRangeName, currentEpoch)
   482→	if err != nil {
   483→		return nil, errors.Wrap(err, "topic from message")
   484→	}
   485→
   486→	// Build the logs.
   487→	var columnsLog interface{} = "all"
   488→	if columnsCount < numberOfColumns {
   489→		columns := request.Columns
   490→		slices.Sort(columns)
   491→		columnsLog = columns
   492→	}
   493→
