   495→		"peer":       pid,
   496→		"topic":      topic,
   497→		"startSlot":  request.StartSlot,
   498→		"count":      request.Count,
   499→		"columns":    columnsLog,
   500→		"totalCount": totalCount,
   501→	})
   502→
   503→	// Send the request.
   504→	stream, err := p.P2P.Send(p.Ctx, request, topic, pid)
   505→	if err != nil {
   506→		if p.DownscorePeerOnRPCFault {
   507→			downscorePeer(p.P2P, pid, "cannotSendDataColumnSidecarsByRangeRequest")
   508→		}
